            .verse(
                act: 3, tag: LocalizedText(en: "No Blame Upon You Today", ur: "No Blame Upon You Today", ar: "No Blame Upon You Today"), surah: 12, ayah: 92,
                arabic: "قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ ۖ يَغْفِرُ ٱللَّهُ لَكُمْ ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ",
                translation: LocalizedText(en: "He said, “No blame upon you today. May God forgive you, and He is the most merciful of the merciful.”", ur: "He said, “No blame upon you today. May God forgive you, and He is the most merciful of the merciful.”", ar: ""),
